#include "proxy_bench_oracle.h"
#include <chrono>
#include <iostream>
#include <array>
struct Workload {std::string username,password,target="example.local",host="proxy.local",response="HTTP/1.1 200 Connection established\r\n\r\n";int port=443;bool handshake=false;};
static Workload work(const std::string &name){Workload w;if(name=="pack")return w;if(name=="authenticated"){w.username="ordinary-user";w.password="ordinary-password";return w;}if(name=="long-auth"){w.username=std::string(256,'u');w.password=std::string(256,'p');return w;}if(name=="handshake"){w.handshake=true;return w;}throw std::runtime_error("workload");}
template<class Proxy>Proxy proxy(const Workload &w){Proxy p;p.username=w.username;p.password=w.password;p.target_host=w.target;p.target_port=w.port;return p;}
static size_t check(const Workload &w){auto old=proxy<upstream_proxy::HttpProxy>(w);auto candidate=proxy<candidate_proxy::HttpProxy>(w);std::array<char,4096> a{},b{};upstream_proxy::String x{a.data(),a.size(),0};candidate_proxy::String y{b.data(),b.size(),0};size_t n,m;if(w.handshake){x.str=const_cast<char*>(w.response.data());y.str=x.str;x.length=y.length=w.response.size();n=old.handshake(&x);m=candidate.handshake(&y);}else{n=old.pack(&x,w.host);m=candidate.pack(&y,w.host);}if(n!=m||a!=b)throw std::runtime_error("native/Rust mismatch");return n;}
template<class Proxy,class Buffer>int measure(const Workload &w,const std::string &engine,const std::string &name,size_t iterations){auto p=proxy<Proxy>(w);std::array<char,4096> output{};Buffer buffer{output.data(),output.size(),0};if(w.handshake){buffer.str=const_cast<char*>(w.response.data());buffer.length=w.response.size();}auto step=[&](){return w.handshake?size_t(p.handshake(&buffer)):p.pack(&buffer,w.host);};size_t expected=check(w),signature=0;for(unsigned i=0;i<128;++i)step();auto start=std::chrono::steady_clock::now();for(size_t i=0;i<iterations;++i)signature+=step();auto end=std::chrono::steady_clock::now();if(signature!=iterations*expected)throw std::runtime_error("timed mismatch");check(w);if(!w.handshake){auto reference=proxy<upstream_proxy::HttpProxy>(w);std::array<char,4096> expected_output{};upstream_proxy::String expected_buffer{expected_output.data(),expected_output.size(),0};reference.pack(&expected_buffer,w.host);if(output!=expected_output)throw std::runtime_error("timed bytes differ");}std::cout<<"{\"engine\":\""<<engine<<"\",\"workload\":\""<<name<<"\",\"operations\":"<<iterations<<",\"ns\":"<<std::chrono::duration_cast<std::chrono::nanoseconds>(end-start).count()<<",\"signature\":"<<signature<<",\"errors\":0}\n";return 0;}
int main(int argc,char **argv){try{
if(argc==2&&std::string(argv[1])=="--check-positive"){
 for(const char *name:{"pack","authenticated"})check(work(name));
 std::cout<<"{\"actual_proxy_workloads\":2,\"verified\":true,\"timed\":false,\"errors\":0}\n";return 0;
}
#ifdef SWR_HTTP_PROXY_POSITIVE
if(argc==2&&std::string(argv[1])=="--check")throw std::runtime_error("Full historical profile is not prepared; use --check-positive");
if(argc==4&&std::string(argv[2])!="pack"&&std::string(argv[2])!="authenticated")throw std::runtime_error("Workload not in prepared positive inventory");
#endif
if(argc==2&&std::string(argv[1])=="--check"){for(const char *name:{"pack","authenticated","long-auth","handshake"})check(work(name));std::cout<<"{\"actual_proxy_workloads\":4,\"errors\":0}\n";return 0;}if(argc!=4)throw std::runtime_error("engine workload iterations required");std::string engine=argv[1],name=argv[2];size_t iterations=std::stoull(argv[3]);if(!iterations)throw std::runtime_error("iterations");if(engine=="native")return measure<upstream_proxy::HttpProxy,upstream_proxy::String>(work(name),engine,name,iterations);if(engine=="rust")return measure<candidate_proxy::HttpProxy,candidate_proxy::String>(work(name),engine,name,iterations);throw std::runtime_error("engine");}catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}}
